/**
 * WorkflowOut
 *
 * One registered workflow: its graph, its capacity, its plugins.
 */
export type WorkflowOut = {
    /**
     * Capacity
     *
     * Slots that pool has, in total.
     */
    capacity: number;
    /**
     * In Flight
     *
     * Slots of that pool leased right now, across every workflow bound to it.
     */
    in_flight: number;
    /**
     * Name
     *
     * The workflow's name, as it appears in URLs.
     */
    name: string;
    /**
     * Nodes
     *
     * Every node of the finalized graph, by name.
     */
    nodes: {
        [key: string]: NodeOut;
    };
    /**
     * What this workflow contributes to the UI (09).
     */
    plugin: WorkflowPlugin;
    /**
     * Pool
     *
     * The pool this workflow's tasks are dispatched on.
     */
    pool: string;
    /**
     * Start
     *
     * The node a new run begins at.
     */
    start: string;
};

/**
 * WorkflowPlugin
 *
 * The panels and actions a workflow contributes (09 §Wire contract).
 *
 * Both lists are empty until the plugin registry lands: the field is
 * part of the contract now so the SPA can read a workflow's plugin
 * surface from the workflow itself, and the entries it will carry are
 * the manifest's own (09).
 */
export type WorkflowPlugin = {
    /**
     * Actions
     *
     * Action declarations, as `/api/plugins` lists them.
     */
    actions?: Array<{
        [key: string]: unknown;
    }>;
    /**
     * Panels
     *
     * Panel declarations, as `/api/plugins` lists them.
     */
    panels?: Array<{
        [key: string]: unknown;
    }>;
};

/**
 * BranchFrame
 *
 * One frame of a task's fan-out stack (04 §Branch frames).
 *
 * Frames nest, outermost first: a branch that fans out again pushes a
 * second frame. ``key`` is the payload that branch was given, which is
 * the branch's identity in every list the SPA groups by it.
 */
export type AthanoreApiSchemasTasksBranchFrame = {
    /**
     * Count
     *
     * How many branches that fan-out opened.
     */
    count: number;
    /**
     * Fanout
     *
     * The task whose return value fanned out.
     */
    fanout: number;
    /**
     * Index
     *
     * This branch's zero-based index in that fan-out.
     */
    index: number;
    /**
     * Key
     *
     * The payload this branch was given.
     */
    key?: unknown;
};

export type AthanoreEventsPayloadsBranchFrame = {
    [key: string]: unknown;
};

